'use client';
import React from 'react';

import { SkinTonePickerLocation } from 'emoji-picker-react/primitives';
import * as Picker from 'emoji-picker-react/primitives';


// App chrome (tabs, Remove, Random) is ordinary consumer UI inside Root.
// Category tabs move to the bottom just by rendering CategoryNav last.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ElementType;
  className?: string;
};

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  return (
    <RootComponent       className={className}
      searchPlaceholder="Filter…"
      skinTonePickerLocation={SkinTonePickerLocation.NONE}
    >
      <div className="notion-tabs">
        <button type="button" aria-pressed="true">
          Emoji
        </button>
        <button type="button" aria-pressed="false">
          Icons
        </button>
        <button type="button" aria-pressed="false">
          Upload
        </button>
        <button type="button" className="notion-remove">
          Remove
        </button>
      </div>
      <div className="notion-search-row">
        <Picker.Search />
        <button type="button" className="notion-random">
          🎲 Random
        </button>
      </div>
      <Picker.Viewport>
        <Picker.List />
        <Picker.Empty />
      </Picker.Viewport>
      <Picker.CategoryNav />
    </RootComponent>
  );
}

/* The surrounding mock app (shared by every stack variant). */
.notion-tabs {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 6px 8px 0;
  border-bottom: 1px solid rgb(55 53 47 / 9%);
  font-size: 14px;
}
.notion-tabs button {
  padding: 6px 8px 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: none;
  color: rgb(55 53 47 / 82%);
  font: inherit;
}
.notion-tabs button[aria-pressed='true'] {
  border-color: #37352f;
  color: #37352f;
}
.notion-tabs .notion-remove {
  margin-left: auto;
}
.notion-search-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 12px 4px;
}
.notion-search-row [data-epr-part='search'] {
  flex: 1;
}
.notion-search-row [data-epr-part='search'] > * {
  padding: 0;
}
.notion-random {
  height: 28px;
  padding: 0 8px;
  border: 1px solid rgb(55 53 47 / 16%);
  border-radius: 6px;
  background: #fff;
  color: #37352f;
  font: inherit;
  font-size: 14px;
}

/* Notion — page icon picker: app tabs and actions around the picker,
   search with a "Random" action, small gray titles, tabs at the bottom. */
/* Picker styles — the source of truth for every stack variant. */
.notion-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #37352f;
  --epr-highlight-color: #2383e2;
  --epr-hover-bg-color: #efefef;
  --epr-focus-bg-color: #e8e8e6;
  --epr-search-input-bg-color: #f1f1ef;
  --epr-search-input-bg-color-active: #f1f1ef;
  --epr-search-border-color: rgb(55 53 47 / 16%);
  --epr-search-border-color-active: #2383e2;
  --epr-search-input-height: 28px;
  --epr-search-input-border-radius: 6px;
  --epr-search-input-padding: 0 8px 0 34px;
  --epr-search-input-placeholder-color: rgb(55 53 47 / 50%);
  --epr-category-label-bg-color: #ffffff;
  --epr-category-label-text-color: rgb(55 53 47 / 82%);
  --epr-category-label-height: 30px;
  --epr-category-icon-active-color: #37352f;
  --epr-category-icon-inactive-color: rgb(55 53 47 / 45%);
  --epr-category-navigation-button-size: 22px;
  --epr-emoji-size: 24px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 12px;
  width: 408px;
  height: 386px;
  border-radius: 10px;
  background: #fff;
  box-shadow:
    rgb(15 15 15 / 5%) 0 0 0 1px,
    rgb(15 15 15 / 10%) 0 3px 6px,
    rgb(15 15 15 / 20%) 0 9px 24px;
  font-family: ui-sans-serif, -apple-system, 'Segoe UI', Helvetica, Arial,
    sans-serif;
  color: #37352f;
}
.notion-picker [data-epr-part='category-label'] {
  font-size: 12px;
  font-weight: 500;
  text-transform: none;
}
.notion-picker [data-epr-part='emoji'] {
  border-radius: 4px;
}
.notion-picker [data-epr-part='category-nav'] {
  border-top: 1px solid rgb(55 53 47 / 9%);
}
.notion-picker [data-epr-part='category-nav'] > * {
  padding: 6px 10px;
}

